EXCLUS = {"_a_supprimer", "archive", "old"}


def trouver(nom):
    """documentation/<nom> en priorité ; sinon ailleurs, hors dossiers d'anciennes copies."""
    if (DOC / nom).exists():
        return DOC / nom
    for p in sorted(VAULT.rglob(nom)):
        if not ({x.lower() for x in p.parts} & EXCLUS) and ".bak" not in p.name:
            return p
    return None


def inserer_apres_3ter(texte, bloc):
    lignes = texte.split("\n")
    debut = None
    for i, l in enumerate(lignes):
        m = re.match(r"^(#{1,4})\s.*3ter", l)
        if m:
            debut, niveau = i, len(m.group(1))
            break
    if debut is None:
        return None, "titre §3ter introuvable"
    fin = len(lignes)
    for j in range(debut + 1, len(lignes)):
        m = re.match(r"^(#{1,4})\s", lignes[j])
        if m and len(m.group(1)) <= niveau:
            fin = j
            break
    nouveau = lignes[:fin] + [""] + bloc.rstrip("\n").split("\n") + [""] + lignes[fin:]
    ou = f"après « {lignes[debut].strip()[:60]} », avant « {lignes[fin].strip()[:60]} »" if fin < len(lignes) else "en fin de fichier"
    return "\n".join(nouveau), ou


def main():
    apply = "--apply" in sys.argv
    if not DOC.is_dir():
        sys.exit(f"✗ dossier documentation/ introuvable ({DOC}) : rien écrit.")
    archive = trouver("BACKLOG_ARCHIVE.md")
    manuel = trouver("USER_MANUAL_COMPLET.md")
    if archive is None or manuel is None:
        sys.exit("✗ BACKLOG_ARCHIVE.md ou USER_MANUAL_COMPLET.md introuvable : rien écrit.")

    actions = []   # (chemin, nouveau contenu, description)
    actions.append((DOC / "HANDOFF_25_OCTOBRE.md", HANDOFF, "handoff du jour"))
    actions.append((DOC / "BACKLOG_ACTIF.md", BACKLOG, "backlog actif remplacé"))

    t = archive.read_text(encoding="utf-8")
    if M_ARCHIVE in t:
        print(f"  · {archive.relative_to(VAULT)} : addendum S28 déjà présent")
    else:
        actions.append((archive, t.rstrip("\n") + "\n\n" + ARCHIVE, "addendum S28 ajouté à la fin"))

    t = manuel.read_text(encoding="utf-8")
    if M_MANUEL in t:
        print(f"  · {manuel.relative_to(VAULT)} : section S28 déjà présente")
    else:
        nouveau, ou = inserer_apres_3ter(t, MANUEL)
        if nouveau is None:
            nouveau, ou = t.rstrip("\n") + "\n\n" + MANUEL, "en fin de fichier (titre §3ter introuvable)"
        actions.append((manuel, nouveau, f"section S28 insérée {ou}"))

    for chemin, contenu, desc in actions:
        etat = "inchangé" if chemin.exists() and chemin.read_text(encoding="utf-8") == contenu else desc
        print(f"  {chemin.relative_to(VAULT)} : {etat}")
    if not apply:
        print("\nAPERÇU : rien écrit. Relancer avec --apply.")
        return
    for chemin, contenu, _ in actions:
        if chemin.exists():
            if chemin.read_text(encoding="utf-8") == contenu:
                continue
            shutil.copy2(chemin, chemin.with_name(chemin.name + ".bak_s28"))
        chemin.write_text(contenu, encoding="utf-8")
    chemins = " ".join(sorted({f'"{c.relative_to(VAULT)}"' for c, _, _ in actions}))
    print("\n✓ Documents posés (sauvegardes .bak_s28). Pour commiter :")
    print(f'  git add {chemins} && git commit -m "Docs 25 oct : handoff, backlog, archive et manuel S28"')


if __name__ == "__main__":
    main()
